<section class="panel links-health-hero"><div class="panel-head"><div><span class="panel-kicker">Routing & 404</span><h2>مركز الروابط والتحويلات</h2><p>أي رابط غير موجود يسجَّل هنا. استخدم تحويل 301 للروابط القديمة حتى لا تفقد الزيارات أو SEO.</p></div></div><div class="links-stats links-stats-four"><div><strong><?=$stats['redirects']?></strong><span>تحويل</span></div><div><strong><?=$stats['404']?></strong><span>روابط 404 مختلفة</span></div><div><strong><?=$stats['404_hits']?></strong><span>إجمالي زيارات 404</span></div><div class="<?=($stats['integrity']??0)?'has-warning':'is-good'?>"><strong><?=$stats['integrity']??0?></strong><span>مشاكل بنيوية مكتشفة</span></div></div></section>

<section class="panel"><div class="panel-head"><div><h2>فحص سلامة الروابط والمحتوى</h2><p>فحص تلقائي للمقالات والصفحات والتصنيفات المنشورة قبل أن تتحول إلى أخطاء 404.</p></div><span class="link-audit-state <?=empty($integrity)?'ok':'warn'?>"><?=empty($integrity)?'✓ لا توجد مشاكل بنيوية':'تحتاج مراجعة'?></span></div><?php if(empty($integrity)):?><div class="empty-state compact"><strong>الروابط البنيوية سليمة</strong><p>سيستمر سجل 404 أدناه في التقاط أي روابط قديمة يصل إليها الزوار.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>النوع</th><th>المشكلة</th><th></th></tr></thead><tbody><?php foreach($integrity as $issue):?><tr><td><?=e($issue['type'])?></td><td><?=e($issue['issue'])?></td><td><a class="btn btn-ghost" href="<?=e($issue['admin'])?>">إصلاح المحتوى</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><div class="panel-head"><h2>إضافة تحويل</h2></div><form method="post" action="/admin/links/redirect/save" class="form-grid"><?=csrf_field()?><label>الرابط القديم<input name="source_path" placeholder="/article/old-slug" required></label><label>الرابط الجديد<input name="target_url" placeholder="/article/new-slug" required></label><label>النوع<select name="http_code"><option value="301">301 دائم</option><option value="302">302 مؤقت</option><option value="307">307 مؤقت</option><option value="308">308 دائم</option></select></label><button class="btn btn-primary">حفظ التحويل</button></form></section>
<section class="panel"><div class="panel-head"><h2>التحويلات الحالية</h2></div><div class="table-wrap"><table><thead><tr><th>القديم</th><th>الجديد</th><th>النوع</th><th></th></tr></thead><tbody><?php foreach($redirects as $r):?><tr><td><code><?=e($r['source_path'])?></code></td><td><code><?=e($r['target_url'])?></code></td><td><?=$r['http_code']?></td><td><form method="post" action="/admin/links/redirect/delete" onsubmit="return confirm('حذف التحويل؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger">حذف</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>سجل أخطاء 404</h2><p>الأعلى تكرارًا أولًا.</p></div><?php if($notFound):?><form method="post" action="/admin/links/404/clear" onsubmit="return confirm('مسح سجل 404؟')"><?=csrf_field()?><button class="btn btn-ghost">مسح السجل</button></form><?php endif;?></div><div class="table-wrap"><table><thead><tr><th>المسار</th><th>الزيارات</th><th>آخر ظهور</th><th>إجراء سريع</th></tr></thead><tbody><?php foreach($notFound as $n):?><tr><td><code><?=e($n['path'])?></code></td><td><strong><?=$n['hits']?></strong></td><td><?=e($n['last_seen_at'])?></td><td><button type="button" class="btn btn-ghost" onclick="document.querySelector('[name=source_path]').value=<?=htmlspecialchars(json_encode($n['path']),ENT_QUOTES,'UTF-8')?>;document.querySelector('[name=source_path]').scrollIntoView({behavior:'smooth'})">إنشاء تحويل</button></td></tr><?php endforeach;?></tbody></table></div></section>
